# <i class="fas fa-server"></i> 13. 테스트
Vue 로 간단하게 title 과 status , priority 를 입력 받아 저장하고 조회하는 화면을 만들어 보았습니다.

<php-GetJson />

```vue
<template>
  <div>
    <ul>
      <li>
        <el-input placeholder="please input title" v-model="model.title"></el-input>
      </li>
      <li>
        <el-input placeholder="please input status" v-model="model.status"></el-input>
      </li>
      <li>
        <el-input placeholder="please input priority" v-model="model.priority"></el-input>
      </li>
      <li>
        <el-input placeholder="please input description" v-model="model.description"></el-input>
      </li>
      <li>
        <el-button type="primary" @click="create">db에 값 저장 하기</el-button>
        <el-button type="primary" @click="search">db에 값 조회 하기</el-button>
      </li>
    </ul>
    <el-table
        :data="tasks"
        border
        style="width: 100%">
      <el-table-column
          prop="task_id"
          label="Task ID"
          width="180">
      </el-table-column>
      <el-table-column
          prop="title"
          label="Title"
          width="180">
      </el-table-column>
      <el-table-column
          prop="start_date"
          label="Start Date">
      </el-table-column>
      <el-table-column
          prop="due_date"
          label="Due Date">
      </el-table-column>
      <el-table-column
          prop="status"
          label="Status">
      </el-table-column>
      <el-table-column
          prop="priority"
          label="Priority">
      </el-table-column>
      <el-table-column
          prop="description"
          label="Description">
      </el-table-column>
      <el-table-column
          prop="created_at"
          label="Create Date">
      </el-table-column>
    </el-table>
  </div>
</template>

<script>
export default {
  name: "GetJson",
  created() {
  },
  data() {
    return {
      model : {
        title : '제목',
        status : '1',
        priority : '1',
        description: '내용',
      },
      tasks : [],
    }
  },
  methods: {
    create() {
      if(this.model.title != '' &&
          this.model.status != '' &&
          this.model.priority != '' &&
          this.model.description != '') {
        this.$http.post('https://goodsaem.ml/tasks',[this.model]).then((response) => {
          this.$message('정상적으로 저장되었습니다.');
        }).catch((err) =>{
          this.$message(err);
        });
      }
    },
    search() {
      this.$http.get('https://goodsaem.ml/tasks').then((response) => {
        this.tasks = response.data;
      })
    }
  }
}
</script>

