        return memoJpaRepo.findAll();
    }

    @PostMapping(value = "/memo")
    public Memo save(@RequestBody Memo memo) {
        return memoJpaRepo.save(memo);
    }
}
```
:::tip 생성자 주입 방식(Constructor Injection)
생성자 주입을 사용하는 이유는 아래 링크를 참고해 주세요
